 static Rig Start(string actual="warrior",string apparent="juggernaut",bool mimic=false,bool masked=true){
  NativeApparentSplashPresentation.Clear();NativeRegroupSession.Rows.Clear();RecruitmentHooks.Forms.Clear();ReactionUtils.Regular=ReactionUtils.Electric=0;ReactionUtils.Throw=false;Entry.Errors.Clear();HotSeatOverlay.IsActive=false;GameManager.Viewing=true;
