  var s=new GameState();var u=new UnitState{UnitData=RecruitmentHooks.Forms[mimic?"warrior":actual],health=mimic?10:100};var from=new Tile{Data=new TileData{coordinates=new(0,0)}};var to=new Tile{Data=new TileData{coordinates=new(1,0),unit=u}};var v=new Unit{UnitState=u};from.unit=v;s.Map.Tiles.AddRange(new[]{from.Data,to.Data});var map=new MapRenderer();map.Tiles.AddRange(new[]{from,to});map.Units[1]=v;MapRenderer.Current=map;GameManager.GameState=s;GameManager.Client=new(){GameState=s};GameManager.LocalPlayer=new();
  NativeRegroupSession.Rows[(Native.Pointer(s),1)]=new(2,1,true,mimic?LedgerActualKind.Mimic:LedgerActualKind.Genuine,masked,masked?Appearance(apparent):null,PaidInvestmentKind.Known,3);
  var reaction=new MoveReaction();reaction.action.Path.Add(new(1,0));reaction.action.Path.Add(new(0,0));var c=new MoveReaction.__c__DisplayClass2_0{unitState=u,__4__this=reaction,fromTile=from,toTile=to,targetTile=to.Data};return new(s,u,v,from,to,c,new(){field_Public___c__DisplayClass2_0_0=c});
 }
 static bool Has(UnitState u,int a)=>UnitDataExtensions.HasAbility(u,(Polytopia.Data.UnitAbility.Type)a);
 static void Begin(Rig r,Action? inside=null){NativeApparentSplashPresentation.BeforeStart(r.Start,out var scope);try{r.End.isStompingUnit=Has(r.Unit,40)||Has(r.Unit,44);inside?.Invoke();if(!r.To.IsHidden&&r.End.isStompingUnit){if(r.Unit.UnitData.weapon==Polytopia.Data.UnitData.WeaponEnum.Burn)ReactionUtils.ElectricStompDamageAnimation(r.To);else ReactionUtils.RegularStompDamageAnimation(r.To);}}finally{NativeApparentSplashPresentation.Finished(null,scope);}}
