 public static int Run(){try{
 Test("safe-pinned-native-hook-registration",()=>{var h=new HarmonyLib.Harmony();NativeApparentSplashPresentation.Install(h);Check(h.Hooks.Count==8,"8 safe presentation hooks");Check(h.Hooks.All(x=>!x.StartsWith("MoveAction")&&!x.StartsWith("Attack")),"no gameplay mutation hook or attack reaction");});
 Test("native-destination-first-path-not-forward-route",()=>{var r=Start(mimic:true);Check(r.Start.__4__this.action.Path[0].X==r.To.Coordinates.X&&r.Start.__4__this.action.Path[1].X==r.From.Coordinates.X,"metadata-audited MoveReaction binds reverse route");Begin(r);End(r);Check(ReactionUtils.Regular==1&&r.To.Area==1,"copied stomp executes on exact native reverse path");var wrong=Start(mimic:true);wrong.Start.__4__this.action.Path=new();wrong.Start.__4__this.action.Path.Add(wrong.From.Coordinates);wrong.Start.__4__this.action.Path.Add(wrong.To.Coordinates);Begin(wrong);End(wrong);Check(ReactionUtils.Regular==0&&wrong.To.Area==0,"malformed reversed callback provenance remains denied");});
 Test("enrolled-opponent-turn-recap-has-visible-source",()=>{var r=Start(mimic:true);GameManager.LocalPlayer!.Id=2;GameManager.Client!.IsRecap=true;Begin(r);End(r);Check(ReactionUtils.Regular==1&&r.To.Area==1,"enrolled live client recap uses same public cue");NoMutation(r);});
 Test("unenrolled-recap-remains-denied",()=>{var r=Start(mimic:true);GameManager.Client!.IsRecap=true;r.State.Admitted=false;Begin(r);End(r);Check(ReactionUtils.Regular+r.To.Area==0,"recap flag alone cannot authorize private state");});
 foreach(bool mimic in new[]{false,true})foreach(string form in new[]{"juggernaut","island","kraken","electric"})Test($"apparent-native-source-{mimic}-{form}",()=>{var r=Start(apparent:form,mimic:mimic);var data=r.Unit.UnitData;Begin(r);Check(r.To.Puff==1&&MapRenderer.Current!.Tiles.All(t=>t.Sway==1),"native puff and every neighbor's sway");Check((form=="electric"?ReactionUtils.Electric:ReactionUtils.Regular)==1,"native apparent weapon cue selected once");Check(r.To.Area==0,"area waits for native movement completion");End(r);Check(r.To.Area==1&&ReferenceEquals(data,r.Unit.UnitData),"one native area sprite and same real data");Check(!Has(r.Unit,40)&&!Has(r.Unit,44),"fake capability never escapes visual callback");NoMutation(r);});
 foreach(string actual in new[]{"juggernaut","island","kraken","electric"})Test("real-passive-under-ordinary-mask-"+actual,()=>{var r=Start(actual,"warrior");Check(Has(r.Unit,40)||Has(r.Unit,44),"real native damage predicate intact before rendering");Begin(r);End(r);Check(ReactionUtils.Regular+ReactionUtils.Electric+r.To.Area==0,"hidden genuine source cue suppressed");Check(Has(r.Unit,40)||Has(r.Unit,44),"real native damage predicate intact afterwards");NoMutation(r);});
 foreach(string actual in new[]{"juggernaut","electric"})Test("matching-real-native-source-dedup-"+actual,()=>{var r=Start(actual,actual);Begin(r);End(r);Check(ReactionUtils.Regular+ReactionUtils.Electric==1&&r.To.Area==1,"matching true/apparent source not duplicated");});
 foreach(bool mimic in new[]{false,true})Test("owner-private-actual-mode-"+mimic,()=>{var r=Start("juggernaut","warrior",mimic);r.Visual.Actual=true;Begin(r);End(r);Check(ReactionUtils.Regular==(mimic?0:1)&&r.To.Area==(mimic?0:1),"private actual follows true source capability");NoMutation(r);});
 Test("observer-apparent-view",()=>{var r=Start(mimic:true);GameManager.LocalPlayer!.Id=2;Begin(r);End(r);Check(ReactionUtils.Regular==1&&r.To.Area==1,"visible enemy copied splash renders");});
 foreach(string guard in new[]{"fog","blackout","invisible","dead","wrong-owner","wrong-root","pooled-renderer","wrong-render-state","unready","replay","spectator","hotseat-overlay","not-viewing","inactive-map","client-state","wrong-path"})Test("guard-"+guard,()=>{var r=Start(mimic:true);switch(guard){case "fog":r.To.IsHidden=true;break;case "blackout":r.To.Data.Explored=false;break;case "invisible":r.Visual.Invisible=true;break;case "dead":r.Unit.health=0;break;case "wrong-owner":r.Unit.owner=2;break;case "wrong-root":r.To.Data.unit=new UnitState();break;case "pooled-renderer":MapRenderer.Current!.Units[1]=new Unit{UnitState=r.Unit};break;case "wrong-render-state":r.Visual.UnitState=new UnitState();break;case "unready":r.State.Admitted=false;break;case "replay":GameManager.Client!.IsReplay=true;break;case "spectator":GameManager.Client!.IsSpectating=true;break;case "recap":GameManager.Client!.IsRecap=true;break;case "hotseat-overlay":HotSeatOverlay.IsActive=true;break;case "not-viewing":GameManager.Viewing=false;break;case "inactive-map":MapRenderer.Current!.gameObject.activeInHierarchy=false;break;case "client-state":GameManager.Client!.GameState=new();break;case "wrong-path":r.Start.fromTile=new Tile{Data=new(){coordinates=new(7,7)}};break;}Begin(r);End(r);Check(ReactionUtils.Regular+ReactionUtils.Electric+r.To.Area==0,"rejected view leaks no fake source cue");});
 foreach(string change in new[]{"map","state","client","player","epoch","profile","logical","root","pool","view","fog","clear"})Test("delayed-completion-revalidates-"+change,()=>{var r=Start();Begin(r);switch(change){case "map":MapRenderer.Current=new();break;case "state":GameManager.GameState=new();break;case "client":GameManager.Client=new();break;case "player":GameManager.LocalPlayer=new();break;case "epoch":r.State.Epoch=Guid.NewGuid();break;case "profile":NativeRegroupSession.Rows[(Native.Pointer(r.State),1)]=NativeRegroupSession.Rows[(Native.Pointer(r.State),1)] with{Appearance=Appearance("warrior")};break;case "logical":NativeRegroupSession.Rows[(Native.Pointer(r.State),1)]=NativeRegroupSession.Rows[(Native.Pointer(r.State),1)] with{LogicalId=9};break;case "root":r.To.Data.unit=new UnitState();break;case "pool":MapRenderer.Current!.Units[1]=new Unit();break;case "view":r.Visual.Actual=true;break;case "fog":r.To.Data.Visible=false;break;case "clear":NativeApparentSplashPresentation.Clear();break;}End(r);Check(r.To.Area==0,"stale delayed borrowed area suppressed");});
 Test("push-does-not-trigger-borrowed-splash",()=>{var r=Start();r.Start.__4__this.action.Reason=2;Begin(r);End(r);Check(!r.End.isStompingUnit&&r.To.Area==0&&ReactionUtils.Regular==0,"push is placement not a passive move");});
