 foreach(bool mimic in new[]{false,true})Test("normal-port-boarding-new-wrapper-"+mimic,()=>{var r=Start(mimic:mimic);var old=r.Unit;var wrapper=new UnitState{id=37,passengerUnit=old,health=mimic?10:100,UnitData=RecruitmentHooks.Forms["warrior"]};r.To.Data.unit=wrapper;var key=(Native.Pointer(r.State),1u);var row=NativeRegroupSession.Rows[key];NativeRegroupSession.Rows.Remove(key);NativeRegroupSession.Rows[(Native.Pointer(r.State),37)]=row with{NativeId=37,Appearance=Appearance("juggernaut") with{Passenger=Appearance("warrior")}};var e=new EmbarkReaction();NativeApparentSplashPresentation.BeforeEmbark(e,out var scope);try{Check(!Has(old,40),"old passenger never acquires source capability");var visual=new Unit{UnitState=wrapper};r.To.unit=visual;MapRenderer.Current!.Units[37]=visual;Check(Has(wrapper,40),"exact rebound root gets apparent source only after native Tile.Render");ReactionUtils.RegularStompDamageAnimation(r.To);r.To.SpawnAreaDamage();}finally{NativeApparentSplashPresentation.Finished(null,scope);}Check(ReactionUtils.Regular==1&&r.To.Area==1&&ReferenceEquals(wrapper.passengerUnit,old)&&wrapper.health==(mimic?10:100),"normal boarding cue without real cargo/root mutation");NativeApparentSplashPresentation.BeforeEmbark(e,out scope);try{Check(!Has(wrapper,40),"repeat exact boarding reaction consumed once");}finally{NativeApparentSplashPresentation.Finished(null,scope);}});
 Test("native-exception-and-clear-do-not-retain-scope",()=>{var r=Start();NativeApparentSplashPresentation.BeforeStart(r.Start,out var scope);Check(Has(r.Unit,40),"visual scope active");var e=new Exception();Check(ReferenceEquals(e,NativeApparentSplashPresentation.Finished(e,scope))&&!Has(r.Unit,40),"native exception propagated with projection removed");NativeApparentSplashPresentation.BeforeStart(r.Start,out scope);NativeApparentSplashPresentation.Clear();NativeApparentSplashPresentation.Finished(null,scope);Check(!Has(r.Unit,40),"stale finalizer cannot restore retired scope");});
